function sourceLinks(hits) {
  const seen = new Set(); const out = [];
  for (const h of hits) {
    const c = h.chunk; const r = Rag.ref(c);
    if (seen.has(r)) continue; seen.add(r);
    const link = /^issue#\d+$/.test(c.path)
      ? `https://github.com/${OWNER}/${REPO}/issues/${c.path.slice(6)}`

if (seen.has(r)) continue; seen.add(r);
    const link = /^issue#\d+$/.test(c.path)
