if(prev!==null&&op){calc();}
else{prev=parseFloat(cur);}
if(expr===''){expr=cur+o;}else{expr+=cur+o;}
op=o;reset=true;
}
function calc(){
if(op===null||prev===null)return;
const a=prev;
const bStr=cur;
const b=parseFloat(cur);
let r;
if(op==='÷')r=a/b;
else if(op==='×')r=a*b;
else if(op==='−')r=a-b;
else if(op==='+')r=a+b;
else return;
expr+=bStr+'='+r;
cur=r.toString();
prev=null;op=null;reset=true;
}
document.querySelectorAll('.buttons button').forEach(b=>{
 b.addEventListener('click',()=>{
 const t=b.textContent;
 if(t>='0'&&t<='9'){digit(t);} 
 else if(t==='.'){dot();}
 else if(t==='C'){clr();}
 else if(t==='±'){sign();}
 else if(t==='%'){pct();}
 else if(t==='√'){sqrt();}
 else if(t==='1/x'){recip();}
 else if(t==='='){calc();}
 else{setOp(t);}
 upd();
 });
});
upd();
})();
</script>
